package net.officefloor.hq.app.person;

/** A hold to add: its from-date (blank: the sheet's today), its to-date (blank: open-ended), and the signed-in user (`by`) adding it. */
public record HoldRequest(String from, String to, String by) {
}
package net.officefloor.hq.app.person;

import java.time.LocalDate;

/** A validated hold: its from-date (null: the sheet's today) and its to-date (null: open-ended). */
public record HoldInput(LocalDate from, LocalDate to) {
}
package net.officefloor.hq.app.person;

import java.time.LocalDate;
import java.time.format.DateTimeParseException;
import net.officefloor.hq.app.BadRequestException;
import net.officefloor.hq.app.session.ChangedBy;
import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.RequestBody;

/** A hold's from-date (blank for the sheet's today) and to-date (blank: open-ended). Publishes them parsed, with the user making the change. */
public class ValidateHold {
    public void validate(@RequestBody HoldRequest request, Out<HoldInput> hold, Out<ChangedBy> changedBy)
            throws BadRequestException {
        ChangedBy by = ChangedBy.of(request == null ? null : request.by());
        LocalDate from = date(request == null ? null : request.from());
        LocalDate to = date(request == null ? null : request.to());
        if (from != null && to != null && to.isBefore(from)) {
            throw new BadRequestException("A hold's to-date cannot be before its from-date");
        }
        hold.set(new HoldInput(from, to));
        changedBy.set(by);
    }

    private static LocalDate date(String value) throws BadRequestException {
        String date = value == null ? "" : value.trim();
        if (date.isEmpty()) {
            return null;
        }
        try {
            return LocalDate.parse(date);
        } catch (DateTimeParseException e) {
            throw new BadRequestException("Enter a date as YYYY-MM-DD");
        }
    }
}
package net.officefloor.hq.app.person;

import java.time.LocalDate;
import java.util.ArrayList;
import java.util.List;
import net.officefloor.hq.app.BadRequestException;
import net.officefloor.hq.app.sheet.SheetRepository;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;

/** Adds a hold to the person, from its from-date (blank: the sheet's today) to its to-date; refuses one ending before it starts. */
public class HoldPerson {
    public void hold(@Val HoldInput input, @Val Person person, PersonRepository repository, SheetRepository sheets,
            Out<HoldSpan> added) throws BadRequestException {
        LocalDate from = input.from() != null ? input.from() : sheets.today(person.getSheetId());
        if (input.to() != null && input.to().isBefore(from)) {
            throw new BadRequestException("A hold's to-date cannot be before its from-date");
        }
        HoldSpan hold = new HoldSpan(from, input.to());
        repository.addHold(person.getId(), hold);
        List<HoldSpan> holds = new ArrayList<>(person.getHolds());
        holds.add(hold);
        person.setHolds(holds);
        added.set(hold);
    }
}
package net.officefloor.hq.app.person;

import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.session.ChangedBy;
import net.officefloor.plugin.variable.Val;

public class RecordPersonHold {
    public void record(@Val Person person, @Val HoldSpan hold, @Val ChangedBy by, Audit audit) {
        audit.record("PERSON_HELD sheet=" + person.getSheetId() + " by=" + by.name() + " name=" + person.getName()
                + " from=" + hold.from());
    }
}
package net.officefloor.hq.app.person;

import java.util.List;

/** A person, with the grade in force on the sheet's today and every grade they were given (each from its from-date), their statement count and their last statement's due-total ("n/a" when it had none) and date
 *  (both null before their first statement), the date they are retired from (null: not retired), their past retirements (in the order kept), whether they have any hold and their holds (in the order added), their patrons' names, sorted, their patrons with their shares of 100.00, sorted by name, their own terms in force on the sheet's today (null: none), their contact (null: none), their tags, sorted (empty: none), their aliases, sorted as names are compared, whether they clash (their name or an alias used on another sheet of their tree) the sheet they were transferred from (null: none) their snapshot lines, oldest first, and their statement lines, one per statement still standing, oldest first, their own terms from the beginning of time (null: none) and the own terms they were given from a date, oldest from-date first. */
public record PersonResponse(long id, String name, String grade, List<GradeResponse> grades, long version, int statementCount, String statedTotal,
        String statementDate, String retiredFrom, List<RetirementResponse> retirements, boolean held, List<HoldResponse> holds,
        List<String> patrons, List<PatronShareResponse> patronShares, Integer terms, String contact, List<String> tags, List<String> aliases,
        boolean clashing, String origin, List<String> snapshots,
        List<String> statementLines, Integer ownTerms, List<TermsResponse> datedTerms) {
    public static PersonResponse from(Person person) {
        Statements s = person.getStatements();
        return new PersonResponse(person.getId(), person.getName(), person.getGrade(),
                person.getGrades().stream().map(GradeResponse::from).toList(), person.getVersion(), s.count(),
                s.count() == 0 ? null : s.lastDueTotal() == null ? "n/a" : s.lastDueTotal().toPlainString(),
                s.lastDate() == null ? null : s.lastDate().toString(),
                person.getRetiredFrom() == null ? null : person.getRetiredFrom().toString(),
                person.getRetirements().stream().map(RetirementResponse::from).toList(), person.isHeld(),
                person.getHolds().stream().map(HoldResponse::from).toList(),
                person.getPatrons(), person.getPatronShares().stream().map(PatronShareResponse::from).toList(),
                person.getTermsToday(), person.getContact(),
                person.getTags() == null ? List.of() : List.of(person.getTags().split(",")), person.getAliases(), person.isClashing(),
                person.getOrigin(), person.getSnapshots().stream().map(SnapshotLine::line).toList(),
                person.getStatementLines().stream().map(StatementLine::line).toList(), person.getTerms(),
                person.getDatedTerms().stream().sorted(java.util.Comparator.comparing(TermsFrom::from))
                        .map(TermsResponse::from).toList());
    }
}
package net.officefloor.hq.app.person;

import net.officefloor.plugin.variable.Val;
import net.officefloor.web.ObjectResponse;

public class RespondWithPerson {
    public void respond(@Val Person person, PersonRepository repository, ObjectResponse<PersonResponse> response) {
        person.setClashing(repository.clashing(person));
        response.send(PersonResponse.from(person));
    }
}
package net.officefloor.hq.app.access;

import net.officefloor.hq.app.BadRequestException;
import net.officefloor.hq.app.session.ChangedBy;
import net.officefloor.hq.app.sheet.SheetRepository;
import net.officefloor.hq.app.sheet.SheetResponse;
import net.officefloor.plugin.variable.Val;

/** Refuses any change by a viewer on the sheet, or to an archived sheet, before it touches the store. */
public class RefuseViewer {
    public void refuse(@Val SheetResponse sheet, @Val ChangedBy by, RoleRepository roles,
            SheetRepository sheets) throws BadRequestException {
        if (roles.isViewer(sheet.id(), by.name())) {
            throw new BadRequestException("A viewer may not change anything on this sheet");
        }
        sheets.refuseArchived(sheet.id());
    }
}
