package net.officefloor.hq.app.person;

import net.officefloor.hq.app.BadRequestException;
import net.officefloor.hq.app.sheet.SheetResponse;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;
import org.springframework.web.bind.annotation.PathVariable;

public class LoadPerson {
    public void load(@Val SheetResponse sheet, @PathVariable("personId") String personId,
            PersonRepository repository, Out<Person> person) throws BadRequestException {
        Person found = null;
        try {
            found = repository.find(sheet.id(), Long.parseLong(personId));
        } catch (NumberFormatException e) {
            // not an id: no such person
        }
        if (found == null) {
            throw new BadRequestException("No such person on this sheet");
        }
        person.set(found);
    }
}
package net.officefloor.hq.app.session;

import net.officefloor.hq.app.BadRequestException;

/** The signed-in user a change is made by, as sent with the change; the audit records it. */
public record ChangedBy(String name) {

    /** The trimmed user, refusing a change sent without one. */
    public static ChangedBy of(String by) throws BadRequestException {
        String name = by == null ? "" : by.trim();
        if (name.isEmpty()) {
            throw new BadRequestException("Sign in to make a change");
        }
        return new ChangedBy(name);
    }
}
    }

    public void setDatedTerms(List<TermsFrom> datedTerms) {
        this.datedTerms = datedTerms;
    }

    /** The sheet's today, as the person was read; null when not known. */
    public LocalDate getToday() {
        return today;
    }

    public void setToday(LocalDate today) {
        this.today = today;
    }

    /** Their own terms in force on the date: those given from the latest from-date on or before it, else those from
     *  the beginning of time (see {@link #getTerms}); null when none. */
    public Integer termsOn(LocalDate on) {
        TermsFrom found = null;
        for (TermsFrom t : datedTerms) {
            if (!t.from().isAfter(on) && (found == null || t.from().isAfter(found.from()))) {
                found = t;
            }
        }
        return found == null ? terms : found.terms();
    }

    /** Their own terms in force on the sheet's today; null when none. */
    public Integer getTermsToday() {
        return today == null ? terms : termsOn(today);
    }

    /** The person's own terms in days from the beginning of time; null when they have none. */
    public Integer getTerms() {
        return terms;
    }
